export function validateReport(r){if(!r||r.schemaVersion!==1||typeof r.id!=='string'||typeof r.task!=='string'||!['blocked','passed','error'].includes(r.outcome)||!Array.isArray(r.steps)||r.steps.length>250||!Array.isArray(r.findings)||r.findings.length>100)throw new Error('Unsupported report format. Use a schemaVersion 1 runner report.');for(const s of r.steps){if(!s||typeof s.key!=='string'||typeof s.screenshot!=='string'||s.screenshot.length>500)throw new Error('Invalid evidence step.');}if(!r.contract||!Array.isArray(r.contract.steps))throw new Error('Report is missing its task contract.');return r;}
export function safeAsset(value){if(typeof value!=='string'||value.includes('..')||value.includes('\\')||!(/^(?:evidence\/|\/reports\/)[a-zA-Z0-9_./-]+\.(png|jpg|webm)$/.test(value)))return null;return value;}
export function bugReport(r){return `# ${r.task}\n\nOutcome: ${r.outcome}\nCaptured: ${r.createdAt}\nBrowser: ${r.engine?.browser}\nTarget: ${r.url}\n\n## Reproduction\n\n${(r.reproduction||[]).map((x,i)=>`${i+1}. ${x}`).join('\n')}\n\n## Findings\n\n${r.findings.map(f=>`### ${f.title}\n${f.summary}\n\n${f.suggestedFix||''}\n\n${f.target?.html?'```html\n'+f.target.html+'\n```':''}`).join('\n\n')}\n\n## Scope\n\nOne keyboard sequence, browser and viewport. This is not a full accessibility audit or WCAG certification.\n`;}
export function regressionTest(r){const fixture=r.fixture?.publicPath;return `// Generated by Can I Finish? Review targets before running against another site.\n// npm install playwright; npx playwright install chromium\n// Start the app with npm start when testing bundled fixtures.\nimport { chromium } from 'playwright';\nimport assert from 'node:assert/strict';\nconst contract = ${JSON.stringify(r.contract,null,2)};\nconst url = process.env.TARGET_URL || ${JSON.stringify(fixture?'http://127.0.0.1:4174/'+fixture:r.url)};\nconst browser = await chromium.launch();\ntry {\n const page = await browser.newPage({ viewport: ${JSON.stringify(r.engine?.viewport||{width:1280,height:900})} });\n await page.goto(url);\n for (const step of contract.steps) {\n  if (step.type === 'press') { await page.keyboard.press(step.key); await page.waitForTimeout(150); await page.waitForLoadState('domcontentloaded'); continue; }\n  const target = page.getByRole(step.role, {name: step.name, exact: true});\n  if (step.type === 'tabTo') {\n   let reached = false;\n   for (let n = 0; n <= step.limit; n++) {\n    if (await target.count() === 1 && await target.evaluate(el => el === document.activeElement)) { reached = true; break; }\n    if (n < step.limit) await page.keyboard.press('Tab');\n   }\n   assert.ok(reached, 'Keyboard target not reached: ' + step.name);\n  } else {\n   await target.waitFor({state: step.type === 'expectVisible' ? 'visible' : 'hidden', timeout: 10000});\n   const visible = await target.count() === 1 && await target.isVisible();\n   assert.equal(visible, step.type === 'expectVisible', 'Unexpected task state: ' + step.name);\n  }\n }\n console.log('Keyboard journey passed');\n} finally { await browser.close(); }\n`;}
